def merge_tool_results(calls, results):
    # Check for duplicate call ids
    ids = [c['id'] for c in calls]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate call ids")

    # Build a map of results by id (last one wins)
    result_map = {}
    for r in results:
        result_map[r['id']] = r.get('content', '')

    # Build the result list in call order
    out = []
    for c in calls:
        call_id = c['id']
        if call_id in result_map:
            out.append({'id': call_id, 'status': 'done', 'content': result_map[call_id]})
        else:
            out.append({'id': call_id, 'status': 'pending'})
    return out

