def summarize_usage(events):
    """Summarize token usage across events.

    Events have request_id and optional nonnegative integer input/output,
    which are cumulative snapshots for that request. For each request, keep the maximum
    seen input and output counts independently, then sum across requests. Missing counts
    mean 0. Reject any negative count with ValueError. Return {'input': total, 'output': total};
    do not mutate events.
    """
    # Track max input/output per request
    max_per_request = {}

    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)

        # Validate non-negative
        if input_count < 0 or output_count < 0:
            raise ValueError("Token counts must be non-negative")

        # Update max per request
        if request_id not in max_per_request:
            max_per_request[request_id] = {'input': 0, 'output': 0}

        max_per_request[request_id]['input'] = max(max_per_request[request_id]['input'], input_count)
        max_per_request[request_id]['output'] = max(max_per_request[request_id]['output'], output_count)

    # Sum across all requests
    total_input = sum(max_per_request[r]['input'] for r in max_per_request)
    total_output = sum(max_per_request[r]['output'] for r in max_per_request)

    return {'input': total_input, 'output': total_output}
